type ttGetter struct {
	calls int
	last  string
	fn    func(call int) (*Trace, error)
}

func (g *ttGetter) GetTrace(_ context.Context, id string) (*Trace, error) {
	g.calls++
	g.last = id
	return g.fn(g.calls)
}

